import { Mesh, PlaneGeometry, Group, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'journal-card-1-label';

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // ---- Engineered backdrop plane (lit, brushed-metal surface) ----
  const planeGeo = new PlaneGeometry(1.9, 0.78, 1, 1);
  const planeMat = new MeshStandardNodeMaterial({
    roughness: 0.62,
    metalness: 0.18,
    transparent: true,
    opacity: 0.92,
  });

  // Load the brushed metal map (async loadAttached)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      planeMat.map = tex;
      planeMat.emissive = new THREE.Color(colors.surface);
      planeMat.emissiveIntensity = 0.04;
      planeMat.needsUpdate = true;
    });
  }

  // Engineered vertical gradient overlay node for the surface plane:
  // a top-down mix from near-black surface to a slightly lifted dark ink.
  const topColor = vec3(new THREE.Color(colors.surface));
  const bottomColor = vec3(new THREE.Color(colors.ink)).mul(float(0.55));
  const gradY = smoothstep(float(0.0), float(1.0), uv().y);
  planeMat.colorNode = mix(bottomColor, topColor, gradY);

  const plane = new Mesh(planeGeo, planeMat);
  plane.position.set(0, 0, 0);
  plane.castShadow = false;
  plane.receiveShadow = true;
  group.add(plane);

  // ---- Thin accent rule (signal red, <=10% of frame) ----
  const accentGeo = new PlaneGeometry(1.9, 0.014);
  const accentMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.accent),
    transparent: true,
    opacity: 0.85,
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.4, 0.002);
  group.add(accentBar);

  // ---- Text label ----
  let headline = null;
  for (const item of items) {
    const frag = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize:
        item.typography?.fontSize == null
          ? undefined
          : item.typography.fontSize,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 0.12,
    });
    if (!frag) continue;
    frag.position.set(0, 0.02, 0.004);
    frag.userData.role = item.role;
    if (item.role === 'headline') {
      headline = frag;
    }
    group.add(frag);
  }

  // ---- Static entrance settle (no primitive requested; keep subtle) ----
  group.scale.setScalar(0.98);
  group.userData._tl = gsap.timeline();
  group.userData._tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.6,
    ease: 'power3.out',
  });

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    if (group.userData._tl) {
      group.userData._tl.kill();
      group.userData._tl = null;
    }
    planeGeo.dispose();
    planeMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (planeMat.map) planeMat.map.dispose();
    group.traverse((child) => {
      if (child.geometry && child.geometry !== planeGeo && child.geometry !== accentGeo) {
        child.geometry.dispose?.();
      }
      if (child.material && child.material !== planeMat && child.material !== accentMat) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material.dispose?.();
        }
      }
    });
  };

  return group;
}
